mapper.insert:
insert ignore into event_reminder_logs (house_id, category, record_id, event_date, notify_date, notify_time)
select house_id, '后备成熟', id, expected_mature_date, curdate(), now()
from replacement_records
where house_id = #{houseId}
  and is_mature_notified = false
  and expected_mature_date <= #{today}

mapper.select:
select *
from event_reminder_logs
where house_id = #{houseId}

    and notify_time >= #{from}


    and notify_time <= #{to}

order by notify_time desc, id desc

    limit #{limit}
